#!/usr/bin/env python3
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parent
LOGO = 'data:image/webp;base64,'

for path in ROOT.glob('*.html'):
    text = path.read_text(encoding='utf-8')
    text = re.sub(r'(<a[^>]*class="logo logo-image"[^>]*>\s*<img\s+src=")[^"]+("[^>]*>)', lambda m: m.group(1) + LOGO + m.group(2), text, flags=re.I)
    text = re.sub(r'(<div[^>]*class="logo logo-image footer-logo"[^>]*>\s*<img\s+src=")[^"]+("[^>]*>)', lambda m: m.group(1) + LOGO + m.group(2), text, flags=re.I)
    path.write_text(text, encoding='utf-8')

css = ROOT / 'styles.css'
css_text = css.read_text(encoding='utf-8')
marker = '/* EXACT AO APPROVED ARTWORK */'
if marker not in css_text:
    css_text += '''

/* EXACT AO APPROVED ARTWORK */
header .logo.logo-image img{
  width:min(440px,calc(100vw - 104px));
  height:auto;
  border-radius:8px;
  box-shadow:none;
}
footer .logo.logo-image img{width:min(560px,100%);height:auto}
@media(max-width:480px){header .logo.logo-image img{width:min(440px,calc(100vw - 104px));}}
'''
    css.write_text(css_text, encoding='utf-8')

print('Exact approved AO artwork applied')
